/* C API of the Rust port of `wrappers.c`, generated by rust-anything. */
#ifndef CORE_WRAPPERS_RS_H
#define CORE_WRAPPERS_RS_H

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#include <sys/types.h>

uint64_t sort_u32_sum(uint64_t seed);
uint32_t sort_u32_elem(uint64_t seed, int64_t idx);
uint64_t sort_r_u32_sum(uint64_t seed);
uint64_t sort_u64_elems(uint64_t seed);
uint64_t sort_u8_elems(uint64_t seed);
uint64_t sort_u32_partial(uint64_t seed, int64_t n);
uint64_t listsort_sum(uint64_t seed);
uint64_t listsort_ties_sum(uint64_t seed);
uint32_t listsort_elem(uint64_t seed, int64_t idx);
uint64_t listsort_small(uint64_t seed, int64_t n);

/* The same functions under `rust_anything_` names, for shadow runs. */
uint64_t rust_anything_sort_u32_sum(uint64_t seed);
uint32_t rust_anything_sort_u32_elem(uint64_t seed, int64_t idx);
uint64_t rust_anything_sort_r_u32_sum(uint64_t seed);
uint64_t rust_anything_sort_u64_elems(uint64_t seed);
uint64_t rust_anything_sort_u8_elems(uint64_t seed);
uint64_t rust_anything_sort_u32_partial(uint64_t seed, int64_t n);
uint64_t rust_anything_listsort_sum(uint64_t seed);
uint64_t rust_anything_listsort_ties_sum(uint64_t seed);
uint32_t rust_anything_listsort_elem(uint64_t seed, int64_t idx);
uint64_t rust_anything_listsort_small(uint64_t seed, int64_t n);

#endif /* CORE_WRAPPERS_RS_H */
